from http.server import BaseHTTPRequestHandler, HTTPServer
from pathlib import Path
from urllib.parse import parse_qs, urlparse
import json
import webbrowser
import pandas as pd

DATA_FILE = Path(__file__).parent / "data/processed/superstore_clean.csv"

def load_data():
    """Reload the cleaned file, so a browser refresh always uses its latest data."""
    data = pd.read_csv(DATA_FILE, parse_dates=["Order Date"])
    data["Sales"] = pd.to_numeric(data["Sales"], errors="coerce").fillna(0)
    data["Profit"] = pd.to_numeric(data["Profit"], errors="coerce").fillna(0)
    data["Year"] = data["Order Date"].dt.year.astype(str)
    return data

def money(value):
    return f"${value / 1_000_000:.2f}M" if abs(value) >= 1_000_000 else f"${value / 1_000:.1f}K" if abs(value) >= 1_000 else f"${value:,.0f}"

def all_options(data):
    return {key: sorted(data[column].dropna().unique(), reverse=key == "year") for key, column in {"year":"Year", "region":"Region", "category":"Category", "segment":"Segment"}.items()}

def filtered(data, query):
    frame = data
    for key, column in {"year":"Year", "region":"Region", "category":"Category", "segment":"Segment"}.items():
        value = query.get(key, [""])[0]
        if value: frame = frame[frame[column] == value]
    return frame

def series(frame, column):
    result = frame.groupby(column, as_index=False).agg(Sales=("Sales","sum"), Profit=("Profit","sum")).sort_values("Sales", ascending=False)
    return [{"label":str(row[column]), "sales":round(row.Sales,2), "profit":round(row.Profit,2)} for _, row in result.iterrows()]

def response(query):
    data = load_data()
    frame = filtered(data, query)
    sales, profit = frame.Sales.sum(), frame.Profit.sum()
    trend = frame.assign(Month=frame["Order Date"].dt.to_period("M").astype(str)).groupby("Month",as_index=False).agg(Sales=("Sales","sum"),Profit=("Profit","sum")).sort_values("Month")
    return {"filters":all_options(data), "metrics":{"sales":money(sales),"profit":money(profit),"orders":f"{frame['Order ID'].nunique():,}","customers":f"{frame['Customer ID'].nunique():,}","margin":f"{profit/sales*100:.1f}%" if sales else "—","rows":f"{len(frame):,}"}, "trend":[{"month":r.Month,"sales":round(r.Sales,2),"profit":round(r.Profit,2)} for _,r in trend.iterrows()], "categories":series(frame,"Category"), "regions":series(frame,"Region")}

