def rendered_page():
    extra_css = EXTRA_STYLE.removeprefix("<style>").removesuffix("</style>") + CONSULTING_STYLE.removeprefix("<style>").removesuffix("</style>")
    return PAGE.replace("</style>", extra_css + "</style>").replace("See the business at a glance.", "Superstore performance at a glance.").replace("Choose a slice of the business below. Every card and chart updates from your cleaned Superstore data.", "Executive view of commercial performance, sourced directly from the validated Superstore dataset.").replace("● Live filters", "● Data connected").replace('<section class="filters">', PIPELINE + '<section class="filters">').replace("</script>", HOVER_SCRIPT + "</script>")

class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        request=urlparse(self.path); api=request.path=="/api"; body=(json.dumps(response(parse_qs(request.query))) if api else rendered_page()).encode()
        self.send_response(200); self.send_header("Content-Type","application/json" if api else "text/html; charset=utf-8"); self.send_header("Content-Length",str(len(body))); self.end_headers(); self.wfile.write(body)
    def log_message(self, format, *args): pass

if __name__ == "__main__":
    address="http://127.0.0.1:8000"; print("Dashboard running at",address); webbrowser.open(address); HTTPServer(("127.0.0.1",8000),Handler).serve_forever()
